data.code:
if ( <this header changes the context> )
    C_NUM := 0;
    F_LAST := current_time();
    F_PERIOD := 1;
    increment_generation_value();
    send_full_header();
elseif ( C_NUM >= F_PERIOD )
    C_NUM := 0;
    F_LAST := current_time();
    F_PERIOD := min(2 * F_PERIOD, F_MAX_PERIOD);
    send_full_header();
elseif ( current_time() > F_LAST + F_MAX_TIME )
    C_NUM := 0;
    F_LAST := current_time();
    send_full_header();
else
    C_NUM := C_NUM + 1
    send_compressed_header();
endif
